with open(sessions_file, 'r') as f:
    lines = f.readlines()

# Find the latest MESSAGE entries
print(f"Total lines in file: {len(lines)}")

# Get latest messages (last 20)
recent_messages = []
for line in reversed(lines[-20:]):
    data = json.loads(line) if '{' in line else None
    if data:
        # Get message type
        if 'type' in data:
            msg_type = data.get('type')
        elif 'message' in data:
            msg = data['message']
            if isinstance(msg, dict):
                msg_type = msg.get('type', str(msg))
            elif isinstance(msg, list):
                msg_type = str(msg[0].get('type', '[list]')) if msg else '[message list]'
            else:
                msg_type = str(msg)
        else:
            msg_type = str(data)

        recent_messages.append((len(lines) - list(reversed([l for l in lines if l])) + list(lines).index(line), msg_type))

# Print unique message types
msg_types = list(set(m[1] for m in recent_messages))
print(f"\ngUnique message types in last 20 messages: {msg_types}")

# Print actual types
print("\n=== Last 20 lines types ===")
for line in reversed(lines[-20:]):
    data = json.loads(line) if '{' in line else {}
    if 'type' in data:
        print(f"{data['type']}")
    elif 'message' in data:
        msg = data['message']
        if isinstance(msg, dict):
            print(f"message:{dict(msg.keys())}")
        else:
            print(f"message:{type(msg)}")
    else:
        print(f"unknown:{data.get('type', 'N/A')}")

